import type { ReadinessLocale } from '../i18n/readinessLocale';
import { resolveCarbonTabLabel } from './complianceTrackLocale';

export const CARBON_WORKSPACE_TABS = [
  { label: 'Bills & activity data', section: 'operational', labelKey: 'operational' },
  { label: 'Overview', section: 'overview', labelKey: 'overview' },
  { label: 'Analytics', section: 'carbon-analytics', labelKey: 'analytics' },
  { label: 'Reduction ideas', section: 'recommendations', labelKey: 'recommendations' },
] as const;

export type CarbonWorkspaceTabSection = (typeof CARBON_WORKSPACE_TABS)[number]['section'];

export const carbonWorkspaceTabLabels = (locale: ReadinessLocale = 'en') =>
  CARBON_WORKSPACE_TABS.map((tab) => resolveCarbonTabLabel(tab.labelKey, locale, tab.label));

export const carbonWorkspaceSectionToTabIndex = (sectionParam: string | null): number => {
  const normalized = sectionParam === 'start-assessment' ? 'overview' : sectionParam;
  const index = CARBON_WORKSPACE_TABS.findIndex((tab) => tab.section === normalized);
  if (index >= 0) {
    return index;
  }
  if (normalized === 'analytics') {
    return CARBON_WORKSPACE_TABS.findIndex((tab) => tab.section === 'carbon-analytics');
  }
  return 2;
};

export const carbonWorkspaceTabIndexToSection = (index: number): CarbonWorkspaceTabSection => {
  return CARBON_WORKSPACE_TABS[Math.max(0, Math.min(index, CARBON_WORKSPACE_TABS.length - 1))].section;
};
